def basis(u, order):
    terms = [1.0]
    for x in u:
        terms.append(x)
    if order in ("pure_quadratic", "quadratic"):
        for x in u:
            terms.append(x * x)
    if order == "quadratic":
        for j in range(len(u)):
            for k in range(j + 1, len(u)):
                terms.append(u[j] * u[k])
    return terms

def normal_matrix(rows, weights):
    m = len(rows[0])
    A = [[0.0] * m for j in range(m)]
    for w, row in zip(weights, rows):
        for j in range(m):
            for k in range(m):
                A[j][k] = A[j][k] + w * row[j] * row[k]
    return A

