def local_quadratic(c):
    n = 1
    while 1 + 2 * n + n * (n - 1) // 2 < len(c):
        n = n + 1
    g = [c[1 + j] for j in range(n)]
    H = [[0.0] * n for j in range(n)]
    for j in range(n):
        H[j][j] = 2 * c[1 + n + j]
    position = 1 + 2 * n
    for j in range(n):
        for k in range(j + 1, n):
            H[j][k] = c[position]
            H[k][j] = c[position]
            position = position + 1
    return g, H

