def ranked(objectives, violations):
    fronts = nondominated_sort(objectives, violations)
    ranks = [0] * len(objectives)
    crowding = [0.0] * len(objectives)
    for r in range(len(fronts)):
        distances = crowding_distance(objectives, fronts[r])
        for i, c in zip(fronts[r], distances):
            ranks[i] = r + 1
            crowding[i] = c
    return fronts, ranks, crowding

def nondominated_sort(objectives, violations):
    remaining = list(range(len(objectives)))
    fronts = []
    while remaining:
        front = []
        for i in remaining:
            beaten = False
            for j in remaining:
                if constrained_dominates(objectives[j], violations[j],
                                         objectives[i], violations[i]):
                    beaten = True
                    break
            if not beaten:
                front.append(i)
        fronts.append(front)
        remaining = [i for i in remaining if i not in front]
    return fronts

def constrained_dominates(a, va, b, vb):
    if va == 0 and vb == 0:
        return dominates(a, b)
    if va == 0:
        return True
    if vb == 0:
        return False
    return va < vb

def dominates(a, b):
    better = False
    for i in range(len(a)):
        if a[i] > b[i]:
            return False
        if a[i] < b[i]:
            better = True
    return better

def violation(constraints):
    total = 0.0
    for c in constraints:
        total = total + max(0.0, c)
    return total

def crowding_distance(objectives, front):
    distance = {i: 0.0 for i in front}
    for k in range(len(objectives[front[0]])):
        order = sorted(front, key=lambda i: (objectives[i][k], i))
        low = objectives[order[0]][k]
        high = objectives[order[-1]][k]
        distance[order[0]] = math.inf
        distance[order[-1]] = math.inf
        if high == low:
            continue
        for p in range(1, len(order) - 1):
            gap = objectives[order[p + 1]][k] - objectives[order[p - 1]][k]
            distance[order[p]] = distance[order[p]] + gap / (high - low)
    return [distance[i] for i in front]

