    if ranks[b] < ranks[a]:
        return b
    if ranks[b] == ranks[a] and crowding[b] > crowding[a]:
        return b
    return a

def survivors(fronts, crowding, mu):
    kept = []
    for front in fronts:
        if len(kept) + len(front) <= mu:
            kept = kept + front
        else:
            order = sorted(front, key=lambda i: (-crowding[i], i))
            kept = kept + order[:mu - len(kept)]
            break
    return sorted(kept)

