def hypervolume(points, reference):
    inside = [p for p in points if p[0] < reference[0] and p[1] < reference[1]]
    area = 0.0
    previous = reference[1]
    for p in sorted(inside, key=lambda p: (p[0], p[1])):
        if p[1] < previous:
            area = area + (reference[0] - p[0]) * (previous - p[1])
            previous = p[1]
    return area

def spaced(objectives, count):
    order = sorted(range(len(objectives)), key=lambda i: (objectives[i][0], i))
    if count >= len(order):
        return order
    scale = []
    for k in range(2):
        values = [objectives[i][k] for i in order]
        width = max(values) - min(values)
        scale.append(width if width > 0 else 1.0)
    arc = [0.0]
    for p in range(1, len(order)):
        a = objectives[order[p - 1]]
        b = objectives[order[p]]
        d1 = (b[0] - a[0]) / scale[0]
        d2 = (b[1] - a[1]) / scale[1]
        arc.append(arc[-1] + math.sqrt(d1 ** 2 + d2 ** 2))
    if count == 1:
        targets = [arc[-1] / 2]
    else:
        targets = [arc[-1] * q / (count - 1) for q in range(count)]
    taken = []
    for t in targets:
        best = None
        for p in range(len(order)):
            if p in taken:
                continue
            if best is None or abs(arc[p] - t) < abs(arc[best] - t):
                best = p
        taken.append(best)
    return [order[p] for p in sorted(taken)]
